    },
    "root": {
      "type": "string",
      "title": "Fleet root",
      "description": "The directory holding your Quest workspaces. Unset, discovery walks up from the session's own directory.",
      "default": ""
    },
    "repos": {
      "type": "string",
      "title": "Repositories",
      "description": "Comma-separated repository names to put on the board, when you would rather name them than discover them. Empty discovers them.",
      "default": ""
    },
    "alerts": {
      "type": "string",
      "title": "Alerts",
      "description": "Toast alerts for a decision waiting on you and for notable task changes, checked every two minutes whether or not the pane is open. 'all' toasts both, 'decisions' only the decisions and the status-line count, 'off' neither.",
      "default": "all",
      "options": [
        "all",
